-- DB: qnfo-audit
-- Rollback: DELETE FROM agent_issues WHERE source = 'session:velocity-quality-cost' AND title IN ('TOKEN-CUT-1: research pipeline neurons per publication 117k to 20k (80-90% lower AI spend)', 'RETENTION-SWEEP-1: shorten retention of the three largest qnfo-audit tables and archive before delete', 'DATA-LAKE-1: move append-only history (verifications, probe log, events) to R2 with a query layer');
-- Charter pillar: cost. Source: measurements of 2026-11-04 (fleet.qnfo.org/api/cost by_worker_7d; qnfo-audit ai_call_counters 7d; d1QueriesAdaptiveGroups 3h).
-- Files the three follow-ups of the velocity/quality/cost session as issues with a named owning loop (OWNER-NO-LOOSE-ENDS-1).

INSERT INTO agent_issues (title, description, source, category, priority, status, created_at, updated_at)
SELECT 'TOKEN-CUT-1: research pipeline neurons per publication 117k to 20k (80-90% lower AI spend)',
'Pillar cost. Owner: QNFO.RSCH program manager and qnfo-research-exec. Measured 7 days to 2026-11-03 (ai_call_counters): research-exec binding:revise 2298 calls (270 errors, 36.9M input tokens, $14.7), ensemble 1189 (154 errors, $11.3), review 1747 (107 errors, $8.9), complete 740 (83 errors, $4.9), reconcile 514 (84 errors, $3.5), verify 656 ($2.1): about $45 of $110 total, 11% of calls errored and were paid for. research_neurons_per_publication_7d = 117571 against a target of 20000. Papers by status (living-paper, all time): 722 published, 120 quarantined (2026-06-29 to 2026-10-04), 91 duplicate (all 2026-07; 74 are arXiv records, 17 slugs), 28 retracted (2026-10-08 to 2026-10-19). That is 239 of 1097 rows, but it is four months of history: only the 28 retractions are recent and none dates after 2026-10-19, so rejected papers are not the main current waste; the errored and repeated calls are. Levers, one change at a time with a prediction each: (1) measured 2026-11-04 (living-paper paper_change_ledger, 7 days): 798 body changes on 690 papers, 607 of them the deterministic PAPER-FORMAT-2 layout sweep (no model call; it still stores a full prior body per change in paper_change_bodies, so living-paper grows: 295 MB), against only about 25 papers published through the release gate and about 10 version bumps: roughly 2300 revise calls and 1189 ensemble calls produced about 35 publications. Find where those calls end without a publication (review-unresolved, revise-noop, errors) and stop the loop earlier: a paper that fails the gate twice parks instead of cycling; (2) do not retry a stage that failed deterministically (270+154+107 errored calls); (3) skip a revise whose review found nothing; (4) run review, verify and reconcile on the cheapest capable model (BUDGET-SOFT-ROUTE-1); (5) trim the 16k-token average revise input to the sections under change. Done when research_neurons_per_publication_7d <= 25000 with output quality measures (v_output_quality_headline) not worse. Closing probe: d1-query on metric research_neurons_per_publication_7d.',
'session:velocity-quality-cost', 'optimization', 'high', 'open', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000
WHERE NOT EXISTS (SELECT 1 FROM agent_issues WHERE title LIKE 'TOKEN-CUT-1:%' AND status = 'open');

INSERT INTO agent_issues (title, description, source, category, priority, status, created_at, updated_at)
SELECT 'RETENTION-SWEEP-1: shorten retention of the three largest qnfo-audit tables and archive before delete',
'Pillar cost. Owner: qnfo-fleet-control (trigger retention_prune_tick_v2) and qnfo-cloud-ops. qnfo-audit is 1.4 GB across 607 tables; no table holds millions of rows (remediation_verifications about 376k with 12 indexes and about 30k inserts a day, cloud_ops_events about 164k, fleet_probe_log about 107k, worker_logs about 47k). The load was rows read: 342M rows in 3 hours from repeated scans of views over those tables (d1QueriesAdaptiveGroups), now about 60 percent lower after the cache tables. Step 1 shipped (migrations/2026-11-04-retention-shorten.sql): remediation_verifications 14 to 8 days (its 7-day readers stay whole), cloud_ops_events housekeeping kinds 14 to 5 days. Step 2: about 15k rows a day land in remediation_verifications, 6.7k of them failing re-probes of the same issue classes, each costing 13 index writes: write a row only when pass or observed changes, or once a day per class, while recording last-probed time in a small table so the freshness views (issues_unprobed_60m) still see the probe; fleet_probe_log from 21 to 7 days; write each deleted batch to R2 as NDJSON first (BACKUP rule), drop the indexes no query plan uses (triggers use INDEXED BY: check them first); register each prune in control_registry. Done when total rows read per hour on qnfo-audit is below 20M for 24 h and the D1 overloaded error count in worker_logs is 0 for 24 h.',
'session:velocity-quality-cost', 'optimization', 'high', 'open', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000
WHERE NOT EXISTS (SELECT 1 FROM agent_issues WHERE title LIKE 'RETENTION-SWEEP-1:%' AND status = 'open');

INSERT INTO agent_issues (title, description, source, category, priority, status, created_at, updated_at)
SELECT 'DATA-LAKE-1: move append-only history (verifications, probe log, events) to R2 with a query layer',
'Pillar cost. Owner: qnfo-cloud-ops with qnfo-ops. D1 is the wrong place for append-only history that is only read in aggregate (qnfo-audit 1.4 GB, 10 s overload windows on scans). Design: workers keep writing the small hot tables; a nightly job exports closed days of remediation_verifications, fleet_probe_log, cloud_ops_events, worker_logs, ai_call_counters history to R2 as partitioned Parquet or NDJSON (day=YYYY-MM-DD), verifies the row count, then deletes from D1 (RETENTION-SWEEP-1); analytical questions run against R2 (R2 SQL or an ops tool that reads the partitions) instead of D1 views. Free-tier first: R2 storage and Class A operations at this volume are within the free allowance; confirm with fleet.qnfo.org/api/cost before enabling. Done when the three tables hold at most 3 days in D1 and an ops query over 30 days of archived verifications returns from R2.',
'session:velocity-quality-cost', 'feature', 'medium', 'open', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000
WHERE NOT EXISTS (SELECT 1 FROM agent_issues WHERE title LIKE 'DATA-LAKE-1:%' AND status = 'open');
